import { useEffect, useMemo, useState } from 'react'
import { z } from 'zod'
import { Card, Select, Spinner } from '@/components/ui'
import { formatCurrency } from '@/lib/format'

const RevenueRow = z.object({
  id: z.string(),
  region: z.string(),
  product: z.string(),
  amount: z.number(),
  date: z.string(),
})
const RevenueResponse = z.object({ rows: z.array(RevenueRow) })
type RevenueRow = z.infer<typeof RevenueRow>

export function RevenueDashboard({ orgId }: { orgId: string }) {
  const [rows, setRows] = useState<RevenueRow[]>([])
  const [region, setRegion] = useState('all')
  const [filteredRows, setFilteredRows] = useState<RevenueRow[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [refreshTick, setRefreshTick] = useState(0)

  useEffect(() => {
    const controller = new AbortController()
    setLoading(true)
    fetch(`/api/orgs/${orgId}/revenue`, { signal: controller.signal })
      .then((res) => res.json())
      .then((json) => {
        setRows(RevenueResponse.parse(json).rows)
        setError(null)
        setLoading(false)
      })
      .catch((err) => {
        if (err.name === 'AbortError') return
        setError('Could not load revenue')
        setLoading(false)
      })
    return () => controller.abort()
  }, [orgId, refreshTick])

  useEffect(() => {
    const id = setInterval(() => setRefreshTick((t) => t + 1), 60_000)
    return () => clearInterval(id)
  }, [])

  useEffect(() => {
    setFilteredRows(region === 'all' ? rows : rows.filter((r) => r.region === region))
  }, [rows, region])

  const total = useMemo(() => filteredRows.reduce((sum, r) => sum + r.amount, 0), [filteredRows])
  const regions = useMemo(() => Array.from(new Set(rows.map((r) => r.region))), [rows])

  if (loading && rows.length === 0) return <Spinner />

  return (
    <Card title="Revenue">
      {error && <p className="text-red-600">{error}</p>}
      <Select value={region} onChange={setRegion}>
        <option value="all">All regions</option>
        {regions.map((r) => (
          <option key={r} value={r}>
            {r}
          </option>
        ))}
      </Select>
      <p className="text-2xl font-semibold">{formatCurrency(total)}</p>
      <table>
        <tbody>
          {filteredRows.map((row) => (
            <tr key={row.id}>
              <td>{row.date}</td>
              <td>{row.product}</td>
              <td>{row.region}</td>
              <td>{formatCurrency(row.amount)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </Card>
  )
}

