import { useEffect, useState } from 'react'
import { z } from 'zod'

const Hit = z.object({ id: z.string(), title: z.string(), snippet: z.string(), url: z.string() })
const SearchResponse = z.object({ hits: z.array(Hit), total: z.number() })
type Hit = z.infer<typeof Hit>

function useDebounced<T>(value: T, delay = 250) {
  const [debounced, setDebounced] = useState(value)
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay)
    return () => clearTimeout(t)
  }, [value, delay])
  return debounced
}

export function SearchResults({ initialQuery = '' }: { initialQuery?: string }) {
  const [query, setQuery] = useState(initialQuery)
  const debouncedQuery = useDebounced(query.trim())
  const [hits, setHits] = useState<Hit[]>([])
  const [total, setTotal] = useState(0)
  const [status, setStatus] = useState<'idle' | 'loading' | 'error'>('idle')

  useEffect(() => {
    if (!debouncedQuery) return
    const controller = new AbortController()
    setStatus('loading')
    fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}`, { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        return res.json()
      })
      .then((json: unknown) => {
        const data = SearchResponse.parse(json)
        setHits(data.hits)
        setTotal(data.total)
        setStatus('idle')
      })
      .catch((err) => {
        if (controller.signal.aborted) return
        console.error(err)
        setStatus('error')
      })
    return () => controller.abort()
  }, [debouncedQuery])

  const visibleHits = debouncedQuery ? hits : []

  return (
    <div className="search">
      <input
        type="search"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search docs…"
        autoFocus
      />
      {status === 'loading' && <span aria-live="polite">Searching…</span>}
      {status === 'error' && <p role="alert">Search failed. Try again.</p>}
      {debouncedQuery && <p className="muted">{total} results</p>}
      <ul>
        {visibleHits.map((hit) => (
          <li key={hit.id}>
            <a href={hit.url}>{hit.title}</a>
            <p>{hit.snippet}</p>
          </li>
        ))}
      </ul>
    </div>
  )
}

