    const avatarUrl = await fetchGravatarUrl(user.email)
    if (!avatarUrl) continue
    await db.user.update({ where: { id: user.id }, data: { avatarUrl } })
    updated++
  }
  console.log(`Done, updated ${updated}`)
}

main().catch((err) => {
  console.error(err)
  process.exit(1)
})

