export async function syncContacts(accountId: string): Promise<number> {
  let cursor: string | undefined
  let synced = 0
  // Pages must be fetched in order: each response carries the cursor for the next page.
  do {
    const params = new URLSearchParams(cursor ? { cursor } : {})
    const res = await fetch(`${CRM_URL}/accounts/${accountId}/contacts?${params}`, {
      headers: { Authorization: `Bearer ${getCrmToken()}` },
    })
    if (!res.ok) throw new Error(`CRM responded ${res.status}`)
    const page = ContactPageSchema.parse(await res.json())
    await upsertContacts(accountId, page.contacts)
    synced += page.contacts.length
    cursor = page.nextCursor ?? undefined
  } while (cursor)
  return synced
}

