import type { User } from '@/types'

type Props = { user: User; onSaved?: (u: User) => void }

export function ProfileEditor({ user, onSaved }: Props) {
  const [displayName, setDisplayName] = useState(user.displayName)
  const [bio, setBio] = useState(user.bio ?? '')
  const [busy, setBusy] = useState(false)

  // keep in sync if the user object is refreshed from the server
  useEffect(() => {
    setDisplayName(user.displayName)
    setBio(user.bio ?? '')
  }, [user.displayName, user.bio])

  async function handleSave() {
    setBusy(true)
    try {
      const updated = await saveProfile(user.id, { displayName, bio }, true, false)
      onSaved?.(updated)
    } finally {
      setBusy(false)
    }
  }

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault()
        void handleSave()
      }}
    >
      <TextField label="Display name" value={displayName} onChange={(e) => setDisplayName(e.target.value)} />
      <TextField label="Bio" multiline value={bio} onChange={(e) => setBio(e.target.value)} />
      <Button type="submit" disabled={busy}>
        {busy ? 'Saving…' : 'Save'}
      </Button>
    </form>
  )
}

