export type CsvRow = Record<string, string | number | null | undefined>

function escapeCell(value: unknown, quoteAll: boolean): string {
  const s = value == null ? '' : String(value)
  const needsQuotes = quoteAll || /[",\r\n]/.test(s)
  return needsQuotes ? `"${s.replace(/"/g, '""')}"` : s
}

export function toCsv(rows: CsvRow[], includeHeaders: boolean, quoteAll: boolean): string {
  if (rows.length === 0) return ''
  const headers = Object.keys(rows[0])
  const lines = rows.map((row) => headers.map((h) => escapeCell(row[h], quoteAll)).join(','))
  if (includeHeaders) lines.unshift(headers.map((h) => escapeCell(h, quoteAll)).join(','))
  return lines.join('\r\n')
}

export function downloadCsv(filename: string, rows: CsvRow[]) {
  const blob = new Blob([toCsv(rows, true, false)], { type: 'text/csv;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  a.click()
  URL.revokeObjectURL(url)
}

