function moveCard(cardId: string, { toColumn, position }: { toColumn: ColumnId; position: number }) {
  setColumns((cols) => {
    const fromColumn = (Object.keys(cols) as ColumnId[]).find((c) => cols[c].some((card) => card.id === cardId))
    if (!fromColumn) return cols
    const card = cols[fromColumn].find((c) => c.id === cardId)!
    const without = { ...cols, [fromColumn]: cols[fromColumn].filter((c) => c.id !== cardId) }
    const target = [...without[toColumn]]
    target.splice(position, 0, card)
    return { ...without, [toColumn]: target }
  })
}

