import { useCallback, useEffect, useState } from 'react'

export type PlayerPrefs = {
  volume: number
  playbackRate: 0.75 | 1 | 1.25 | 1.5 | 2
  autoplayNext: boolean
  captionsLang: string | null
}

const KEY = 'player:prefs:v2'
const DEFAULTS: PlayerPrefs = { volume: 0.8, playbackRate: 1, autoplayNext: true, captionsLang: null }

function load(): PlayerPrefs {
  const raw = localStorage.getItem(KEY)
  if (!raw) return DEFAULTS
  try {
    return { ...DEFAULTS, ...(JSON.parse(raw) as Partial<PlayerPrefs>) }
  } catch {
    return DEFAULTS
  }
}

export function usePlayerPrefs() {
  const [prefs, setPrefs] = useState<PlayerPrefs>(load)

  useEffect(() => {
    function onStorage(e: StorageEvent) {
      if (e.key === KEY) setPrefs(load())
    }
    window.addEventListener('storage', onStorage)
    return () => window.removeEventListener('storage', onStorage)
  }, [])

  const update = useCallback((patch: Partial<PlayerPrefs>) => {
    setPrefs((prev) => {
      const next = { ...prev, ...patch }
      localStorage.setItem(KEY, JSON.stringify(next))
      return next
    })
  }, [])

  return [prefs, update] as const
}

