import { useEffect, useState } from 'react'
import { z } from 'zod'

const Tick = z.object({ symbol: z.string(), price: z.number(), change: z.number(), ts: z.number() })
type Tick = z.infer<typeof Tick>

export function LiveTicker({ symbols }: { symbols: string[] }) {
  const [ticks, setTicks] = useState<Record<string, Tick>>({})
  const [connected, setConnected] = useState(false)
  const symbolKey = symbols.join(',')

  useEffect(() => {
    const es = new EventSource(`/api/stream/ticks?symbols=${encodeURIComponent(symbolKey)}`)
    es.onopen = () => setConnected(true)
    es.onerror = () => setConnected(false)
    es.onmessage = (event) => {
      let payload: unknown
      try {
        payload = JSON.parse(event.data)
      } catch {
        return
      }
      const parsed = Tick.safeParse(payload)
      if (!parsed.success) return
      setTicks((prev) => ({ ...prev, [parsed.data.symbol]: parsed.data }))
    }
    return () => es.close()
  }, [symbolKey])

  return (
    <div className="ticker" data-connected={connected}>
      {symbols.map((symbol) => {
        const t = ticks[symbol]
        return (
          <span key={symbol} className={t && t.change < 0 ? 'down' : 'up'}>
            {symbol} {t ? t.price.toFixed(2) : '—'}
          </span>
        )
      })}
    </div>
  )
}

