import { useState } from 'react'
import { inviteMember } from '@/lib/api/team'
import { Button, Progress, Textarea } from '@/components/ui'

function parseEmails(text: string) {
  return Array.from(
    new Set(
      text
        .split(/[\s,;]+/)
        .map((e) => e.trim().toLowerCase())
        .filter((e) => e.includes('@')),
    ),
  )
}

export function BulkInvite({ teamId }: { teamId: string }) {
  const [text, setText] = useState('')
  const [done, setDone] = useState(0)
  const [failed, setFailed] = useState<string[]>([])
  const [running, setRunning] = useState(false)
  const emails = parseEmails(text)

  async function handleInvite() {
    setRunning(true)
    setDone(0)
    setFailed([])
    for (const email of emails) {
      try {
        await inviteMember(teamId, { email, role: 'member' })
      } catch {
        setFailed((prev) => [...prev, email])
      }
      setDone((n) => n + 1)
    }
    setRunning(false)
  }

  return (
    <div className="bulk-invite">
      <Textarea value={text} onChange={(e) => setText(e.target.value)} placeholder="Paste email addresses" rows={6} />
      <p>{emails.length} addresses detected</p>
      {running && <Progress value={done} max={emails.length} />}
      {failed.length > 0 && (
        <ul className="errors">
          {failed.map((email) => (
            <li key={email}>{email}</li>
          ))}
        </ul>
      )}
      <Button onClick={handleInvite} disabled={running || emails.length === 0}>
        Send invites
      </Button>
    </div>
  )
}

