type Props = { src: string; poster?: string; muted?: boolean; onEnded?: () => void }

export function VideoPlayer({ src, poster, muted: initiallyMuted = false, onEnded }: Props) {
  const videoRef = useRef<HTMLVideoElement>(null)
  const [muted, setMuted] = useState(initiallyMuted)
  const [playing, setPlaying] = useState(false)
  const [progress, setProgress] = useState(0)

  useEffect(() => {
    const video = videoRef.current
    if (!video) return
    const onTime = () => setProgress(video.duration ? video.currentTime / video.duration : 0)
    const onPlay = () => setPlaying(true)
    const onPause = () => setPlaying(false)
    video.addEventListener('timeupdate', onTime)
    video.addEventListener('play', onPlay)
    video.addEventListener('pause', onPause)
    return () => {
      video.removeEventListener('timeupdate', onTime)
      video.removeEventListener('play', onPlay)
      video.removeEventListener('pause', onPause)
    }
  }, [src])

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.target instanceof HTMLInputElement) return
      const video = videoRef.current
      if (!video) return
      if (e.key === ' ') {
        e.preventDefault()
        if (video.paused) void video.play()
        else video.pause()
      }
      if (e.key === 'm') setMuted((m) => !m)
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])

  return (
    <div className="player">
      <video ref={videoRef} src={src} poster={poster} muted={muted} onEnded={onEnded} />
      <div className="player__bar">
        <button onClick={() => (playing ? videoRef.current?.pause() : void videoRef.current?.play())}>
          {playing ? 'Pause' : 'Play'}
        </button>
        <div className="player__progress" style={{ width: `${progress * 100}%` }} />
        <button onClick={() => setMuted((m) => !m)}>{muted ? 'Unmute' : 'Mute'}</button>
      </div>
    </div>
  )
}

