import { useEffect, useMemo, useState } from 'react'
import { uploadImage } from '@/lib/uploads'

type Pending = { id: string; file: File }

export function ImageUploader({ albumId, onUploaded }: { albumId: string; onUploaded: (ids: string[]) => void }) {
  const [pending, setPending] = useState<Pending[]>([])
  const [uploading, setUploading] = useState(false)
  const [progress, setProgress] = useState(0)

  const previews = useMemo(() => pending.map((p) => ({ id: p.id, url: URL.createObjectURL(p.file) })), [pending])
  useEffect(() => () => previews.forEach((p) => URL.revokeObjectURL(p.url)), [previews])

  function addFiles(files: FileList | null) {
    if (!files) return
    const next = Array.from(files, (file) => ({ id: crypto.randomUUID(), file }))
    setPending((prev) => [...prev, ...next])
  }

  async function uploadAll() {
    setUploading(true)
    const uploaded: string[] = []
    // Upload one file at a time on purpose: the album API processes images
    // synchronously and returns 503 when a client has more than one upload in flight.
    for (const [i, p] of pending.entries()) {
      const { id } = await uploadImage(albumId, p.file)
      uploaded.push(id)
      setProgress((i + 1) / pending.length)
    }
    setUploading(false)
    setPending([])
    onUploaded(uploaded)
  }

  return (
    <div className="uploader">
      <input type="file" accept="image/*" multiple onChange={(e) => addFiles(e.target.files)} />
      <div className="uploader__grid">
        {previews.map((p) => (
          <figure key={p.id}>
            <img src={p.url} alt="" />
            <button onClick={() => setPending((prev) => prev.filter((x) => x.id !== p.id))} disabled={uploading}>
              Remove
            </button>
          </figure>
        ))}
      </div>
      {uploading && <progress value={progress} max={1} />}
      <button onClick={uploadAll} disabled={uploading || pending.length === 0}>
        Upload {pending.length}
      </button>
    </div>
  )
}

