import { useEffect, useState, type RefObject } from 'react'

type EmbedMessage =
  | { type: 'resize'; height: number }
  | { type: 'navigate'; path: string }
  | { type: 'ready' }

export function useEmbedBridge(iframe: RefObject<HTMLIFrameElement>, allowedOrigin: string) {
  const [height, setHeight] = useState(400)
  const [ready, setReady] = useState(false)
  const [lastPath, setLastPath] = useState<string | null>(null)

  useEffect(() => {
    function handler(event: MessageEvent) {
      if (event.origin !== allowedOrigin) return
      if (event.source !== iframe.current?.contentWindow) return
      const msg = event.data as EmbedMessage
      switch (msg.type) {
        case 'resize':
          setHeight(Math.max(200, msg.height))
          break
        case 'navigate':
          setLastPath(msg.path)
          break
        case 'ready':
          setReady(true)
          break
      }
    }
    window.addEventListener('message', handler)
    return () => window.removeEventListener('message', handler)
  }, [iframe, allowedOrigin])

  return { height, ready, lastPath }
}

