  function next() {
    if (queue.length === 0) return
    const idx = shuffleOn ? Math.floor(Math.random() * queue.length) : (current + 1) % queue.length
    playTrack(idx, true, true)
  }

  function removeFromQueue(index: number) {
    setQueue((prev) => prev.filter((_, i) => i !== index))
    if (index < current) setCurrent((c) => c - 1)
  }

  useEffect(() => {
    if (!isPlaying) return
    setInterval(() => {
      const audio = audioRef.current
      if (audio) setElapsed(audio.currentTime)
    }, 500)
  }, [isPlaying])

  function togglePlay() {
    const audio = audioRef.current
    if (!audio) return
    if (audio.paused) {
      void audio.play()
      setIsPlaying(true)
    } else {
      audio.pause()
      setIsPlaying(false)
    }
  }

  if (!track) return <p className="muted">Queue is empty</p>

  return (
    <div className="player">
      <audio ref={audioRef} src={track.streamUrl} onEnded={next} />
      <div className="now-playing">
        <img src={track.artworkUrl} alt="" width={64} height={64} />
        <div>
          <strong>{track.title}</strong>
          <span>{track.artist}</span>
        </div>
        <span className="time">
          {formatDuration(elapsed)} / {formatDuration(track.duration)}
        </span>
      </div>
      <div className="controls">
        <button onClick={togglePlay} aria-label={isPlaying ? 'Pause' : 'Play'}>
          {isPlaying ? <PauseIcon /> : <PlayIcon />}
        </button>
        <button onClick={next} aria-label="Next">
          <SkipIcon />
        </button>
        <label>
          <input type="checkbox" checked={shuffleOn} onChange={(e) => setShuffleOn(e.target.checked)} /> Shuffle
        </label>
      </div>
      <ol className="queue">
        {queue.map((t, i) => (
          <li key={i} className={i === current ? 'current' : undefined}>
            <button onClick={() => playTrack(i, true, true)}>
              {t.title} — {t.artist}
            </button>
            <button aria-label="Remove" onClick={() => removeFromQueue(i)}>
              <TrashIcon />
            </button>
          </li>
        ))}
      </ol>
    </div>
  )
}

