import { useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { checkoutApi, type Address, type ShippingRate } from '@/lib/api/checkout'
import { useCart } from '@/features/cart/useCart'
import { AddressForm, Button, Radio, Spinner, TextField } from '@/components/ui'
import { formatMoney } from '@/lib/format'
import { analytics } from '@/lib/analytics'

type Props = {
  savedAddress: Address | null
  couponCode?: string
  onCouponApplied?: (code: string) => void
}

export function CheckoutPage({ savedAddress, couponCode = '', onCouponApplied }: Props) {
  const navigate = useNavigate()
  const { cart, clearCart } = useCart()
  const [address, setAddress] = useState<Address | null>(savedAddress)
  const [rates, setRates] = useState<ShippingRate[]>([])
  const [rateId, setRateId] = useState<string | null>(null)
  const [ratesLoading, setRatesLoading] = useState(false)
  const [coupon, setCoupon] = useState(couponCode)
  const [couponError, setCouponError] = useState<string | null>(null)
  const [discount, setDiscount] = useState(0)
  const [orderPlaced, setOrderPlaced] = useState(false)
  const [orderId, setOrderId] = useState<string | null>(null)
  const [placing, setPlacing] = useState(false)

  useEffect(() => {
    setCoupon(couponCode)
  }, [couponCode])

  useEffect(() => {
    if (!address) return
    setRatesLoading(true)
    checkoutApi.shippingRates({ address, items: cart.items }).then((result) => {
      setRates(result)
      setRateId((current) => current ?? result[0]?.id ?? null)
      setRatesLoading(false)
    })
  }, [address, cart.items])

  useEffect(() => {
    if (!orderPlaced || !orderId) return
    analytics.track('order_placed', { orderId, total: cart.total })
    clearCart()
    navigate(`/orders/${orderId}/confirmation`)
  }, [orderPlaced, orderId])

  const selectedRate = rates.find((r) => r.id === rateId) ?? null
  const total = useMemo(
    () => cart.subtotal - discount + (selectedRate?.amount ?? 0),
    [cart.subtotal, discount, selectedRate],
  )

  async function applyCoupon() {
    setCouponError(null)
    try {
      const result = await checkoutApi.validateCoupon(coupon.trim())
      setDiscount(result.discount)
      onCouponApplied?.(coupon.trim())
    } catch {
      setDiscount(0)
      setCouponError('That code is not valid')
    }
  }

  async function placeOrder() {
    if (!address || !selectedRate) return
    setPlacing(true)
    try {
      const order = await checkoutApi.placeOrder({
        items: cart.items,
        address,
        shippingRateId: selectedRate.id,
        coupon: discount > 0 ? coupon.trim() : undefined,
      })
      setOrderId(order.id)
      setOrderPlaced(true)
    } finally {
      setPlacing(false)
    }
  }

  return (
    <div className="checkout">
      <section>
        <h2>Shipping address</h2>
        <AddressForm value={address} onChange={setAddress} />
      </section>

      <section>
        <h2>Delivery</h2>
        {ratesLoading && <Spinner />}
        {!ratesLoading && rates.length === 0 && address && <p>No delivery options for this address.</p>}
        {rates.map((rate) => (
          <Radio key={rate.id} name="rate" checked={rate.id === rateId} onChange={() => setRateId(rate.id)}>
            {rate.label} — {formatMoney(rate.amount)} ({rate.estimatedDays} days)
          </Radio>
        ))}
      </section>

      <section>
        <h2>Promo code</h2>
        <TextField value={coupon} onChange={(e) => setCoupon(e.target.value)} error={couponError ?? undefined} />
        <Button variant="secondary" onClick={applyCoupon} disabled={!coupon.trim()}>
          Apply
        </Button>
      </section>

      <section className="checkout__summary">
        <dl>
          <dt>Subtotal</dt>
          <dd>{formatMoney(cart.subtotal)}</dd>
          {discount > 0 && (
            <>
              <dt>Discount</dt>
              <dd>-{formatMoney(discount)}</dd>
            </>
          )}
          <dt>Shipping</dt>
          <dd>{selectedRate ? formatMoney(selectedRate.amount) : '—'}</dd>
          <dt>Total</dt>
          <dd>{formatMoney(total)}</dd>
        </dl>
        <ul className="checkout__items">
          {cart.items.map((item) => (
            <li key={item.sku}>
              {item.quantity} × {item.name}
            </li>
          ))}
        </ul>
        <Button onClick={placeOrder} disabled={placing || !selectedRate}>
          {placing ? 'Placing order…' : `Pay ${formatMoney(total)}`}
        </Button>
      </section>
    </div>
  )
}
